mapper.select:
SELECT uc.id, uc.folder_id AS folderId, cf.name AS folderName, uc.note, uc.create_time AS createTime, uc.update_time AS updateTime, b.id AS "blog.id", b.title AS "blog.title", b.summary AS "blog.summary", b.cover_img AS "blog.coverImage", b.author_id AS "blog.authorId", u.nickname AS "blog.authorNickname", u.avatar AS "blog.authorAvatar", b.category_id AS "blog.categoryId", c.name AS "blog.categoryName", b.status AS "blog.status", b.visibility AS "blog.visibility", b.is_top AS "blog.isTop", b.view_count AS "blog.viewCount", (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS "blog.likeCount", (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS "blog.commentCount", b.publish_time AS "blog.publishTime", b.create_time AS "blog.createTime", b.update_time AS "blog.updateTime", b.status_changed_time AS "blog.statusChangedTime", b.id AS blogId, b.title AS blogTitle, b.summary AS blogSummary, u.nickname AS authorName, b.view_count AS viewCount FROM tb_user_collection uc INNER JOIN tb_collection_folder cf ON uc.folder_id = cf.id AND cf.deleted = 0 INNER JOIN tb_blog b ON uc.target_id = b.id AND uc.target_type = 'blog' LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id WHERE uc.user_id = #{userId} AND uc.deleted = 0 AND b.deleted = 0
AND uc.folder_id = #{folderId}
ORDER BY uc.create_time DESC

SELECT * FROM tb_user_collection
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND deleted = 0
LIMIT 1
